__d(function(o,e,n,t,a,i,r){a.exports={path:"/how-to-install",title:"How to Install the Go Do App on iPhone and Android",description:"Go Do isn't in the App Store or Google Play yet, but you can install it on your iPhone or Android phone in a few seconds. Step-by-step instructions with pictures.",kicker:"Get the app",h1:"How to install Go Do",lead:"Go Do isn't in the App Store or Google Play yet \u2014 but you don't have to wait. Go Do is a web app, so you can add it to your phone's Home Screen in about 10 seconds. It opens full screen, gets its own icon, sends notifications and updates itself automatically, just like any other app.",jump:[{label:"Install on iPhone",id:"iphone",icon:"logo-apple"},{label:"Install on Android",id:"android",icon:"logo-android"},{label:"Or use in a browser",id:"computer",icon:"globe-outline"}],sections:[{id:"iphone",heading:"iPhone and iPad",paragraphs:["Use Safari \u2014 it's the browser that can add web apps to the Home Screen on iPhone."],steps:[{title:"Open go-do.live in Safari",body:"Open the Safari app and go to go-do.live.",image:"/install/iphone-1.png"},{title:"Tap the Share button",body:"Tap the Share button \u2014 the square with an arrow pointing up \u2014 at the bottom of the screen (on iPad it's at the top).",image:"/install/iphone-2.png"},{title:"Tap \u201cAdd to Home Screen\u201d",body:"Scroll down the list and tap Add to Home Screen. If you don't see it, tap Edit Actions at the bottom and add it.",image:"/install/iphone-3.png"},{title:"Tap \u201cAdd\u201d",body:"Leave the name as Go Do and tap Add in the top-right corner.",image:"/install/iphone-4.png"},{title:"Open Go Do from your Home Screen",body:"Tap the new Go Do icon, log in or create your free account, and turn on notifications so you know when friends invite you. (Notifications need iOS 16.4 or newer.)",image:"/install/iphone-5.png"}]},{id:"android",heading:"Android",paragraphs:["Use Google Chrome. (Samsung Internet works the same way: open the menu and choose Add page to \u203a Home screen.)"],steps:[{title:"Open go-do.live in Chrome",body:"Open the Chrome app and go to go-do.live.",image:"/install/android-1.png"},{title:"Tap the \u22ee menu",body:"Tap the three dots in the top-right corner of Chrome.",image:"/install/android-2.png"},{title:"Tap \u201cInstall app\u201d or \u201cAdd to Home screen\u201d",body:"Choose Install app. On some phones it says Add to Home screen.",image:"/install/android-3.png"},{title:"Tap \u201cInstall\u201d",body:"Confirm by tapping Install (or Add).",image:"/install/android-4.png"},{title:"Open Go Do from your Home screen",body:"Find the Go Do icon on your Home screen or in your app drawer, open it, log in, and allow notifications.",image:"/install/android-5.png"}]},{id:"computer",heading:"On a computer",paragraphs:["You don't need to install anything \u2014 just go to go-do.live in any browser and log in. Go Do has a full layout made for bigger screens.","If you'd like it in its own window, Chrome and Microsoft Edge show an Install button in the address bar when you're on go-do.live."]},{id:"faq",heading:"Questions",faq:[["When will Go Do be in the App Store and Google Play?","We're working on it. When it's ready you'll be able to switch over and keep your account, friends and plans."],["Is the Home Screen version really an app?","Yes. It opens full screen with its own icon, remembers your login, sends notifications and updates itself \u2014 it just comes from the web instead of an app store."],["Does it cost anything?","No. Go Do is completely free."],["I don't see \u201cAdd to Home Screen\u201d on my iPhone.","Make sure you're in Safari (not Chrome or another app's built-in browser). In the Share menu, scroll to the bottom and tap Edit Actions to add it."],["How do I remove it?","Press and hold the Go Do icon and choose Remove App (iPhone) or Uninstall (Android), just like any other app."]]}],cta:{heading:"Installed? Let's find something to do.",body:"Create your free account and see what's happening near you this week.",actions:[{label:"Create a free account",href:"/welcome",primary:!0},{label:"What is Go Do?",href:"/what-is-go-do"}]}}},1002,[]);